    async def execute_flow(
        self,
        name: str,
        *,
        target_override: typing.Optional[FlowTargetOverride] = OMIT,
        parameters: typing.Optional[typing.Dict[str, typing.Any]] = OMIT,
        calibration_session_id: typing.Optional[str] = OMIT,
        idempotency_key: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ExecuteFlowResponse:
        """
        Execute a Flow via Prefect deployment, as one run of a calibration session.

        The run is recorded before it is launched. It joins ``calibration_session_id`` when given
        (refused before launch if that session cannot take it); otherwise an automatic session
        created for it. Every step execution of the run
        carries the run ID, and the session ID when it has one. ``idempotency_key`` makes a retry
        return the recorded run instead of starting another.

        Parameters
        ----------
        name : str

        target_override : typing.Optional[FlowTargetOverride]
            Targets for this run, overriding the initial targets of every CalibrationSession.run (or legacy CalibService.run) and pipeline

        parameters : typing.Optional[typing.Dict[str, typing.Any]]
            Execution parameters (overrides default_parameters)

        calibration_session_id : typing.Optional[str]
            Add the run to this calibration session, which must exist, be open, be on the run's chip, and be created by the signed-in user; otherwise the request is refused before anything starts. It groups the run with the session's other work and grants nothing. Without it, the run joins an automatic session created for it.

        idempotency_key : typing.Optional[str]
            A retry with the same key and request returns the recorded run instead of starting another, and a run whose launch outcome is unknown is never launched again with it. Without a key, every request starts a new run.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ExecuteFlowResponse
            Successful Response

        Examples
        --------
        import asyncio

        from qdash.sdk._generated import AsyncQDashApi

        client = AsyncQDashApi(
            project_id="YOUR_PROJECT_ID",
            token="YOUR_TOKEN",
            base_url="https://yourhost.com/path/to/api",
        )


        async def main() -> None:
            await client.flow.execute_flow(
                name="name",
                parameters={"max_iterations": 5, "qids": ["32", "38"]},
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.execute_flow(
            name,
            target_override=target_override,
            parameters=parameters,
            calibration_session_id=calibration_session_id,
            idempotency_key=idempotency_key,
            request_options=request_options,
        )
        return _response.data

